# Test the pattern on the demo input
import os
import json

def load_all_grids():
    d = os.environ['RLM_SESSION_DIR']
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    return t

def transform(grid):
    result = [row[:] for row in grid]  # deep copy

    # For each row, if 6 at c-1 and c+1, then c becomes 2
    for r in range(len(grid)):
        for c in range(1, len(grid[r]) - 1):
            if grid[r][c-1] == 6 and grid[r][c+1] == 6 and grid[r][c] != 6:
                result[r][c] = 2
    return result

def load_demo_pair():
    d = os.environ['RLM_SESSION_DIR']
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read()
    lines = t.split('\n')

    inp_lines = []
    out_lines = []

    in_idx = out_idx = 0
    for i, line in enumerate(lines):
        if 'Demo pair 1 input (27x7):' in line:
            in_idx = i + 1
        elif 'Demo pair 1 output' in line:
            out_idx = i + 1

    # Parse input (27 rows)
    for line in lines[in_idx:in_idx+27]:
        if line.strip():
            inp_lines.append([int(x) for x in line.split()])

    # Parse output (27 rows)
    for line in lines[out_idx+1:out_idx+28]:
        if line.strip():
            out_lines.append([int(x) for x in line.split()])

    return inp_lines, out_lines

inp_demos, out_demos = load_demo_pair()

# Apply transform
out_calc = transform(inp_demos)

# Check if matches
matches = True
for r in range(len(inp_demos)):
    for c in range(len(inp_demos[0])):
        if out_demos[r][c] != out_calc[r][c]:
            print(f"Mismatch at ({r},{c}): demo={out_demos[r][c]}, calc={out_calc[r][c]}")
            matches = False

if matches:
    print("Pattern matches demo output!")
    print("\nCalculated output:")
    for row in out_calc:
        print(" ".join(map(str, row)))

